        "type": "page",
        "name": "page.tsx",
        "code": "\"use client\"\n\nimport { PlusIcon } from \"lucide-react\"\nimport { useState } from \"react\"\n\nimport { Button } from \"@/components/ui/button\"\nimport {\n  type ColumnVisibility,\n  ColumnViewOptions,\n} from \"@/components/openlmis/column-view-options\"\nimport { SearchInput } from \"@/components/openlmis/search-input/search-input\"\nimport { SelectFilter } from \"@/components/openlmis/select-filter\"\n\nimport {\n  ListToolbar,\n  ListToolbarEnd,\n  ListToolbarFilter,\n  ListToolbarSearch,\n} from \"@/components/blocks/openlmis/list-toolbar\"\n\nconst COLUMNS = [\n  { id: \"name\", label: \"Name\" },\n  { id: \"email\", label: \"Email\" },\n  { id: \"status\", label: \"Status\" },\n]\n\nexport default function Page() {\n  const [query, setQuery] = useState(\"\")\n  const [status, setStatus] = useState(\"\")\n  const [visibility, setVisibility] = useState<ColumnVisibility>({})\n\n  return (\n    <div className=\"w-full max-w-5xl p-8 pb-56\">\n      <ListToolbar>\n        <ListToolbarSearch>\n          <SearchInput onValueChange={setQuery} value={query} />\n        </ListToolbarSearch>\n        <ListToolbarFilter>\n          <SelectFilter\n            label=\"Status\"\n            onValueChange={setStatus}\n            options={[\n              { value: \"active\", label: \"Active\" },\n              { value: \"inactive\", label: \"Inactive\" },\n            ]}\n            value={status}\n          />\n        </ListToolbarFilter>\n        <ListToolbarEnd>\n          <ColumnViewOptions\n            columns={COLUMNS}\n            onReset={() => setVisibility({})}\n            onVisibilityChange={setVisibility}\n            visibility={visibility}\n          />\n          <Button>\n            <PlusIcon data-icon=\"inline-start\" />\n            Add User\n          </Button>\n        </ListToolbarEnd>\n      </ListToolbar>\n    </div>\n  )\n}",
